fails, execution rolls back to the xbegin() call with an ABORT return value.
void atomic_add(int* loc, int val)
{
int result = xbegin();
if (result == SUCCESS)
{
*loc += val;
xend();
}
else
{
lock();
*loc += val;
unlock();
}
